targets.expr:
topk(25,
  100 - avg by (job, instance) (
    rate(node_cpu_seconds_total{
      cluster=~"$cluster",
      job=~"$job",
      instance=~"$instance",
      mode="idle"
    }[$__rate_interval])
  ) * 100
)

topk(25, 100 -
(
  avg by (job, instance) (
    node_memory_MemAvailable_bytes{cluster=~"$cluster", job=~"$job", instance=~"$instance"}
  )
  /
  avg by (job, instance) (
    node_memory_MemTotal_bytes{cluster=~"$cluster", job=~"$job", instance=~"$instance"}
  )
) * 100)
